const email = {
  subject: inputData.subject,
  body: inputData.body || inputData.bodyPlain,
  from: inputData.from
};

const response = await fetch('https://api.anthropic.com/v1/messages', {
  method: 'POST',
  headers: {
    'x-api-key': process.env.CLAUDE_API_KEY,
    'content-type': 'application/json'
  },
  body: JSON.stringify({
    model: 'claude-3-5-sonnet-20241022',
    max_tokens: 500,
    system: 'Analyze this customer email and score priority: HIGH (urgent/upset), MEDIUM (normal), or LOW (info request). Return only the priority level.',
    messages: [{
      role: 'user',
      content: `Email Subject: ${email.subject}\n\nEmail Body: ${email.body}`
    }]
  })
});

const data = await response.json();
const priority = data.content[0].text.trim().toUpperCase();

return {
  priority: priority,
  subject: email.subject,
  from: email.from
};
